UPDATE semantic_outbox SET state='claimed', lease_token=lower(hex(randomblob(16))), lease_expires_at=?1+?2, claim_owner=?3, attempt_count=attempt_count+1, updated_at=?4 WHERE task_id = CASE WHEN EXISTS(SELECT 1 FROM semantic_outbox INDEXED BY semantic_outbox_ready WHERE state='pending' AND available_at<=?1 AND space_id=?5) THEN (SELECT task_id FROM semantic_outbox INDEXED BY semantic_outbox_fifo_pending WHERE space_id=?5 AND state='pending' AND available_at<=?1 ORDER BY task_id ASC LIMIT 1) ELSE NULL END RETURNING task_id, lease_token, doc_key, doc_version, input_digest, op, lease_expires_at